'use strict';

// MODULES //

var tape = require( 'tape' );
var copy = require( '@stdlib/utils/copy' );
var isArray = require( '@stdlib/assert/is-array' );
var anyBy = require( '@stdlib/array/base/any-by' );
var isValid = require( './../lib' );


// FUNCTIONS //

/**
* Returns the first flow code node having a directive.
*
* @private
* @param {Array} children - semantic children
* @returns {(Object|null)} code node
*/
function directedCode( children ) {
	var out;
	var i;

	for ( i = 0; i < children.length; i++ ) {
		if ( children[ i ].type === 'code' && children[ i ].directiveRefs.length ) {
			return children[ i ];
		}
		if ( children[ i ].children ) {
			out = directedCode( children[ i ].children );
			if ( out ) {
				return out;
			}
		}
	}
	return null;
}

/**
* Creates an embedded-code resource from a flow code node.
*
* @private
* @param {Object} code - flow code node
* @param {Array} refs - directive refs
* @returns {Object} embedded-code resource
*/
function embeddedCode( code, refs ) {
	return {
		'id': 'embedded-code[review:0]',
		'language': code.language,
		'lang': code.lang,
		'meta': code.meta,
		'value': code.value,
		'role': code.role,
		'execution': code.execution,
		'directiveRefs': refs,
		'source': code.source,
		'sourceHash': code.sourceHash,
		'payloadHash': code.payloadHash
	};
}


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof isValid, 'function', 'main export is a function' );
	t.end();
});

tape( 'the function returns `true` if provided a valid semantic document', function test( t ) {
	var bool;
	var pkg;

	pkg = require( './fixtures/good.json' );
	bool = isValid( pkg );

	t.strictEqual( bool, true, 'returns expected value' );
	t.strictEqual( isValid.errors, null, 'returns expected value' );
	t.end();
});

tape( 'the function returns `false` if provided an invalid semantic document', function test( t ) {
	var bool;
	var pkg;

	pkg = {
		'beep': 'boop'
	};
	bool = isValid( pkg );

	t.strictEqual( bool, false, 'returns expected value' );
	t.strictEqual( isArray( isValid.errors ), true, 'returns expected value' );
	t.end();
});

tape( 'the function validates semantic ID and reference integrity', function test( t ) {
	var bool;
	var pkg;
	var raw;

	raw = require( './fixtures/good.json' );

	pkg = copy( raw );
	pkg.titleRef = 'missing';
	bool = isValid( pkg );

	t.strictEqual( bool, false, 'returns expected value' );
	t.strictEqual( isValid.errors[ 0 ].keyword, 'semanticIntegrity', 'returns expected value' );

	pkg = copy( raw );
	pkg.children[ 1 ].id = pkg.children[ 0 ].id;
	bool = isValid( pkg );

	t.strictEqual( bool, false, 'returns expected value' );
	t.end();
});

tape( 'the function reports wrong-type directive references without throwing', function test( t ) {
	var code;
	var bool;
	var pkg;
	var raw;

	raw = require( './fixtures/good.json' );

	pkg = copy( raw );
	pkg.resources.directives[ 0 ].targetRefs = [ pkg.titleRef ];
	bool = isValid( pkg );

	t.strictEqual( bool, false, 'returns expected value' );
	t.ok( anyBy( isValid.errors, hasTypeError ), 'returns expected value' );

	pkg = copy( raw );
	code = directedCode( pkg.children );
	code.directiveRefs = [ pkg.titleRef ];
	pkg.resources.directives[ 0 ].targetRefs = [];
	bool = isValid( pkg );

	t.strictEqual( bool, false, 'returns expected value' );
	t.end();

	function hasTypeError( err ) {
		return err.params.code === 'reference-type';
	}
});

tape( 'the function reports duplicate IDs which collide with directive targets without throwing', function test( t ) {
	var resource;
	var code;
	var bool;
	var pkg;
	var raw;

	raw = require( './fixtures/good.json' );

	// Duplicate a directive-targeted code node ID on a subsequently registered flow node:
	pkg = copy( raw );
	code = directedCode( pkg.children );
	pkg.children[ 2 ].children[ 3 ].children[ 0 ].id = code.id;
	bool = isValid( pkg );

	t.strictEqual( bool, false, 'returns expected value' );
	t.ok( anyBy( isValid.errors, hasDuplicateError ), 'returns expected value' );

	// Duplicate a directive ID on an embedded-code resource:
	pkg = copy( raw );
	code = directedCode( pkg.children );
	resource = embeddedCode( code, [] );
	resource.id = pkg.resources.directives[ 0 ].id;
	pkg.resources.embeddedCode.push( resource );
	bool = isValid( pkg );

	t.strictEqual( bool, false, 'returns expected value' );
	t.ok( anyBy( isValid.errors, hasDuplicateError ), 'returns expected value' );
	t.end();

	function hasDuplicateError( err ) {
		return err.params.code === 'duplicate-id';
	}
});

tape( 'the function validates embedded-code directive relationships bidirectionally', function test( t ) {
	var directive;
	var code;
	var pkg;
	var raw;

	raw = require( './fixtures/good.json' );

	pkg = copy( raw );
	code = directedCode( pkg.children );
	directive = pkg.resources.directives[ 0 ];
	code.directiveRefs = [];
	directive.targetRefs = [];
	pkg.resources.embeddedCode.push( embeddedCode( code, [ directive.id ] ) );

	t.strictEqual( isValid( pkg ), false, 'returns expected value' );

	pkg = copy( raw );
	code = directedCode( pkg.children );
	directive = pkg.resources.directives[ 0 ];
	code.directiveRefs = [];
	pkg.resources.embeddedCode.push( embeddedCode( code, [] ) );
	directive.targetRefs = [ pkg.resources.embeddedCode[ 0 ].id ];

	t.strictEqual( isValid( pkg ), false, 'returns expected value' );
	t.end();
});
